<script setup>
import { Link,useForm } from '@inertiajs/vue3';
const props=defineProps({branch:Object,counts:Object});
const form=useForm({notes:''});
function create(){form.post(`/admin/branches/${props.branch.id}/inventory/counts`,{preserveScroll:true,onSuccess:()=>form.reset()});}
const status={draft:'مسودة',posted:'تم الترحيل',cancelled:'ملغي'};
</script>
<template><main dir="rtl" class="mx-auto max-w-6xl space-y-6 p-4 sm:p-6"><header><Link :href="`/admin/branches/${branch.id}/inventory`" class="text-sm font-bold text-amber-700">المخزون</Link><h1 class="mt-1 text-3xl font-black">الجرد الفعلي</h1><p class="mt-1 text-sm text-slate-500">إنشاء جلسة جرد، إدخال الكميات الفعلية، ثم ترحيل فروق المخزون.</p></header><form @submit.prevent="create" class="flex flex-wrap gap-3 rounded-2xl border bg-white p-5"><input v-model="form.notes" placeholder="ملاحظات الجرد" class="min-w-[250px] flex-1 rounded-lg border-slate-300"/><button class="rounded-lg bg-slate-900 px-5 py-2.5 font-bold text-white">بدء جرد جديد</button></form><section class="overflow-hidden rounded-2xl border bg-white"><div v-for="count in counts.data" :key="count.id" class="flex flex-wrap items-center justify-between gap-3 border-b p-4"><div><p class="font-black">جرد #{{count.id}}</p><p class="mt-1 text-xs text-slate-500">{{new Date(count.counted_at).toLocaleString('ar-EG')}} · {{count.items_count}} مكون</p></div><span class="rounded-full bg-slate-100 px-3 py-1 text-xs font-bold">{{status[count.status]||count.status}}</span><Link :href="`/admin/branches/${branch.id}/inventory/counts/${count.id}`" class="rounded-lg border px-4 py-2 text-sm font-bold">فتح الجرد</Link></div><p v-if="!counts.data.length" class="p-8 text-center text-sm text-slate-500">لم يتم إنشاء عمليات جرد بعد.</p></section></main></template>
